#!/bin/bash\n\n# Screen Time Child App Build & Deploy Script\n# This script helps build and deploy the companion mobile apps\n\necho \"🔥 Building Screen Time Child Device Apps 🔥\"\necho \"============================================\"\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Function to print colored output\nprint_status() {\n    echo -e \"${BLUE}[INFO]${NC} $1\"\n}\n\nprint_success() {\n    echo -e \"${GREEN}[SUCCESS]${NC} $1\"\n}\n\nprint_warning() {\n    echo -e \"${YELLOW}[WARNING]${NC} $1\"\n}\n\nprint_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\n# Check if we're in the right directory\nif [ ! -d \"ScreenTimeChild\" ]; then\n    print_error \"ScreenTimeChild directory not found. Please run this script from /app directory.\"\n    exit 1\nfi\n\ncd ScreenTimeChild\n\n# Check if React Native CLI is available\nif ! command -v npx &> /dev/null; then\n    print_error \"npx not found. Please install Node.js and npm first.\"\n    exit 1\nfi\n\nprint_status \"Checking React Native environment...\"\nnpx react-native doctor\n\necho \"\\n📱 Select deployment option:\"\necho \"1. Build Android APK (Debug)\"\necho \"2. Build Android APK (Release)\"\necho \"3. Build iOS App (requires Mac)\"\necho \"4. Run on Android Device/Emulator\"\necho \"5. Run on iOS Simulator (requires Mac)\"\necho \"6. Generate Pairing Code Test\"\nread -p \"Enter your choice (1-6): \" choice\n\ncase $choice in\n    1)\n        print_status \"Building Android APK (Debug)...\"\n        cd android\n        ./gradlew assembleDebug\n        if [ $? -eq 0 ]; then\n            print_success \"Debug APK built successfully!\"\n            print_status \"APK location: android/app/build/outputs/apk/debug/app-debug.apk\"\n            print_status \"Install command: adb install android/app/build/outputs/apk/debug/app-debug.apk\"\n        else\n            print_error \"Failed to build debug APK\"\n        fi\n        ;;\n    2)\n        print_status \"Building Android APK (Release)...\"\n        cd android\n        ./gradlew assembleRelease\n        if [ $? -eq 0 ]; then\n            print_success \"Release APK built successfully!\"\n            print_status \"APK location: android/app/build/outputs/apk/release/app-release.apk\"\n            print_warning \"Remember to sign the APK before distribution\"\n        else\n            print_error \"Failed to build release APK\"\n        fi\n        ;;\n    3)\n        print_status \"Building iOS App...\"\n        if [[ \"$OSTYPE\" == \"darwin\"* ]]; then\n            cd ios\n            xcodebuild -workspace ScreenTimeChild.xcworkspace -scheme ScreenTimeChild -configuration Release archive\n            if [ $? -eq 0 ]; then\n                print_success \"iOS app built successfully!\"\n                print_status \"Archive created. Use Xcode to export IPA file.\"\n            else\n                print_error \"Failed to build iOS app\"\n            fi\n        else\n            print_error \"iOS builds require macOS. Please use a Mac to build iOS app.\"\n        fi\n        ;;\n    4)\n        print_status \"Running on Android device/emulator...\"\n        npx react-native run-android\n        ;;\n    5)\n        print_status \"Running on iOS simulator...\"\n        if [[ \"$OSTYPE\" == \"darwin\"* ]]; then\n            npx react-native run-ios\n        else\n            print_error \"iOS simulator requires macOS. Please use a Mac to run iOS app.\"\n        fi\n        ;;\n    6)\n        print_status \"Testing pairing code generation...\"\n        echo \"\\n📋 Testing API connectivity:\"\n        \n        # Test backend connectivity\n        BACKEND_URL=\"https://safeweb-kids-1.preview.emergentagent.com/api\"\n        echo \"Testing connection to: $BACKEND_URL\"\n        \n        curl -s \"$BACKEND_URL/\" | grep -q \"healthy\" \n        if [ $? -eq 0 ]; then\n            print_success \"Backend API is healthy and reachable\"\n        else\n            print_error \"Cannot reach backend API. Check internet connection.\"\n        fi\n        \n        print_status \"\\nTo test full pairing flow:\"\n        echo \"1. Open parent dashboard at https://safeweb-kids-1.preview.emergentagent.com\"\n        echo \"2. Login and navigate to Device Control\"\n        echo \"3. Click 'Pair New Device' to generate code\"\n        echo \"4. Install and run this app on child's device\"\n        echo \"5. Enter pairing code in the app\"\n        ;;\n    *)\n        print_error \"Invalid choice. Please run the script again.\"\n        exit 1\n        ;;\nesac\n\necho \"\\n🎉 Build process completed!\"\necho \"\\n📚 Next Steps:\"\necho \"1. Install the app on child's device\"\necho \"2. Grant necessary permissions:\"\necho \"   - iOS: Screen Time access, Family Sharing\"\necho \"   - Android: Device Admin, Usage Access, Accessibility\"\necho \"3. Pair device using parent dashboard\"\necho \"4. Test remote control functionality\"\necho \"\\n🔗 Parent Dashboard: https://safeweb-kids-1.preview.emergentagent.com\"\necho \"📖 Documentation: /app/DEPLOYMENT_GUIDE.md\""